 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      pushText(tokens, template.slice(pos));
+      break;
+    }
+    pushText(tokens, template.slice(pos, open));
+
+    const raw = template.startsWith("{{{", open);
+    const closer = raw ? "}}}" : "}}";
+    const start = open + (raw ? 3 : 2);
+    const close = template.indexOf(closer, start);
+    if (close === -1) throw new Error("unterminated tag");
+
+    tokens.push(classify(template.slice(start, close).trim(), raw));
+    pos = close + closer.length;
+  }
+
+  return tokens;
 }
+
+function pushText(tokens: Token[], text: string): void {
+  if (text === "") return;
+  const last = tokens[tokens.length - 1];
+  if (last?.kind === "text") last.text += text;
+  else tokens.push({ kind: "text", text });
+}
+
+function classify(inner: string, raw: boolean): Token {
+  if (raw) return { kind: "value", expr: inner, raw: true };
+  if (inner === "else") return { kind: "else" };
+  if (inner === "/if") return { kind: "end" };
+  if (inner.startsWith("#if ")) return { kind: "if", path: inner.slice(4).trim() };
+  return { kind: "value", expr: inner, raw: false };
+}
